TLM.f("Sancti/08-24",{"officium":"S. Bartholomæi Apostoli","rule":["ex C1;","Gloria","Credo","Prefatio=Apostolis"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1","sections":{"Introitus":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui hujus diei venerándam sanctámque lætítiam in beáti Apóstoli tui Bartholomǽi festivitáte tribuísti: da Ecclésiæ tuæ, quǽsumus; et amáre quod crédidit, et prædicáre quod dócuit."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 12:27-31"},{"k":"text","la":"Fratres: Vos estis corpus Christi et membra de membro. Et quosdam quidem pósuit Deus in Ecclésia primum apóstolos, secúndo prophetas, tertio doctores, deinde virtútes, exinde grátias curationum, opitulatiónes, gubernatiónes, genera linguarum, interpretatiónes sermonum. Numquid omnes apóstoli? numquid omnes prophétæ? numquid omnes doctóres? numquid omnes virtútes? numquid omnes grátiam habent curationum? numquid omnes linguis loquúntur? numquid omnes interpretántur? Æmulámini autem charísmata melióra."}],"Graduale":[{"k":"ref","la":"Ps 44:17; 44:18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine."},{"k":"text","la":"Pro patribus tuis nati sunt tibi fílii: proptérea pópuli confitebúntur tibi.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Te gloriósus Apostolórum chorus laudat, Dómine. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 6:12-19"},{"k":"text","la":"In illo témpore: Exiit Jesus in montem oráre, et erat pernóctans in oratióne Dei. Et cum dies factus esset, vocavit discípulos suos, et elégit duódecim ex ipsis - quos et Apóstolos nominávit -: Simónem, quem cognominávit Petrum, et Andream fratrem ejus, Jacóbum et Joánnem, Philíppum et Bartholomæum, Matthǽum et Thomam, Jacóbum Alphæi et Simónem, qui vocátur Zelótes, et Judam Jacóbi, et Judam Iscariótem, qui fuit próditor. Et descéndens cum illis, stetit in loco campéstri, et turba discipulórum ejus, et multitúdo copiósa plebis ab omni Judæa, et Jerúsalem, et marítima, et Tyri, et Sidónis, qui vénerant, ut audírent eum et sanaréntur a languóribus suis. Et, qui vexabántur a spirítibus immúndis, curabántur. Et omnis turba quærébat eum tángere: quia virtus de illo exíbat, et sanábat omnes."}],"Offertorium":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Secreta":[{"k":"text","la":"Beáti Apóstoli tui Bartholomǽi sollémnia recenséntes, quǽsumus, Dómine: ut ejus auxílio tua benefícia capiámus, pro quo tibi laudis hóstias immolámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Mt 19, 28"},{"k":"text","la":"Vos, qui secúti estis me, sedébitis super sedes, iudicántes duódecim tribus Israel, dicit Dóminus."}],"Postcommunio":[{"k":"text","la":"Sumptum, Dómine, pignus redemptiónis ætérnæ: sit nobis, quǽsumus; interveniénte beáto Bartholomǽo Apóstolo tuo, vitæ præséntis auxílium páriter et futúræ."},{"k":"macro","name":"Per Dominum"}]},"hr":{"4ce2969ae90d1d66":{"t":"Ps 138, 17, Ps 138, 1-2\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove."},"f1dc628eeddeb039":{"t":"<i>Pomolimo se</i>.\nSvemogući, vječni Bože, koji si dao časno i sveto veselje ovoga dana u svetkovini (spomenu) tvoga blaženoga apostola Bartolomeja udijeli svojoj Crkvi, molimo te, da ljubi što je on vjerovao i propovijeda što je učio.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"comemoratione → ∅"},"1e741f4bd4323fed":{"t":"1 Kor 12, 27-31\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: Vi ste Kristovo tijelo i među sobom združeni udovi. Tako je Bog u Crkvi postavio prvo apostole, drugo proroke, treće učitelje, zatim moći, onda one koji liječe, koji pomažu, koji upravljaju, koji govore različite jezike i tumače nauke. Zar su svi apostoli? Svi proroci? Svi učitelji? Svi moći? Zar imaju svi dar liječenja? Govore li svi jezike? Zar svi tumače? Težite da postignete uzvišeni je duhovne darove!"},"a386a817ce6388c4":{"t":"Ps 44, 17-18\nPostavit ćeš ih za knezove nad svom zemljom, spominjat će tvoje ime, Gospodine. Mjesto tvojih otaca rodit će ti se sinovi, zato će te narodi slaviti.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nTebe, Gospodine, hvali slavni apostola zbor. <i>Aleluja</i>."},"537e029daaf52910":{"t":"Lk 6, 12–19\nSlijedi sveto Evanđelje po Luki. U ono vrijeme uzađe Isus na goru da moli i prenoćio je u molitvi. A kad se razdani, pozva svoje učenike, te između njih izabra dvanaestoricu koje prozove apostolima: Simuna, kojega je nazvao Petar i njegova brata Andriju, Jakova i Ivana, Filipa i Bartolomeja, Mateja i Tomu, Jakova Alfejeva i Simuna Revnitelja i Judu Jakovljeva i Judu Iškariota koji je bio izdajica. I siđe s njima i ustavi se u dolini i s njim mnoštvo njegovih učenika i vrlo mnogo naroda iz sve Judeje i Jeruzalema i primorja tirskoga i sidonskoga, koji su došli do ga čuju i da se izliječe od svojih bolesti. I ozdravljali su svi koje su mučili nečisti duhovi. I sav je narod nastojao da ga se dotakne jer je iz njega izlazila moć i liječio je sve."},"8bade162dbdb175e":{"t":"Ps 138, 17\nNada sve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove."},"0d476d4ab776c3b4":{"t":"Slaveći blagdan (spomen) tvoga blaženoga apostola Bartolomeja, dok ti prinosimo žrtvu hvale molimo te, Gospodine, da s njegovom pomoću primimo tvoja dobročinstva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"memoriam → ∅"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"40768fcd5f6d8f44":{"t":"Mt 19, 28\nVi koji ste pošli za mnom sjedit ćete na prijestoljima i suditi dvanaest plemena Izraelovih, govori Gospodin."},"ce0602a5ddcae44f":{"t":"<i>Pomolimo se</i>.\nPrimljeni zalog vječnog otkupljenja bio nam, Gospodine, po zagovoru tvoga blaženog apostola Bartolomeja pomoć za sadašnji i za budući život.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
